import sys
from itertools import product

def read_input():
    import sys
    input = sys.stdin.read().split()
    n, m, k, w = map(int, input[:4])
    levels = []
    index = 4
    for _ in range(k):
        level = []
        for _ in range(n):
            level.append(input[index])
            index += 1
        levels.append(level)
    return n, m, k, w, levels

def diff_count(level1, level2, n, m):
    count = 0
    for i, j in product(range(n), range(m)):
        if level1[i][j] != level2[i][j]:
            count += 1
    return count

def solve(n, m, k, w, levels):
    dp = [[float('inf')] * k for _ in range(k)]
    path = [[None] * k for _ in range(k)]

    for i in range(k):
        dp[i][i] = 0

    for length in range(2, k + 1):
        for i in range(k - length + 1):
            j = i + length - 1
            for p in range(i, j):
                cost = dp[i][p] + diff_count(levels[p], levels[j], n, m) * w
                if cost < dp[i][j]:
                    dp[i][j] = cost
                    path[i][j] = p

    total_cost = float('inf')
    best_start = None
    for i in range(k):
        if dp[i][k - 1] + n * m < total_cost:
            total_cost = dp[i][k - 1] + n * m
            best_start = i

    def reconstruct_path(start, end):
        if start == end:
            return [(start + 1, 0)]
        else:
            mid = path[start][end]
            return reconstruct_path(start, mid) + [(end + 1, mid + 1)]

    transfer_plan = reconstruct_path(best_start, k - 1)
    return total_cost, transfer_plan

def main():
    n, m, k, w, levels = read_input()
    total_cost, transfer_plan = solve(n, m, k, w, levels)
    print(total_cost)
    for x, y in transfer_plan:
        print(x, y)

main()
